namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
use App\Models\Concerns\HasAudits;


/**
 * Generated Eloquent model for the pengesahan_pendaftaran table.
 */
class RegistrationApproval extends Model 
{
	use HasFactory;
    use HasAudits;
    use SoftDeletes;
    
    
    /**
     *
     * @var string
     */
    protected $table = 'pengesahan_pendaftaran';
    /**
     *
     * @var string
     */
    protected $primaryKey = 'id';
    /**
     *
     * @var array<int, string>
     */
    protected $fillable = [
        
        'pendaftaran_id',
        'user_id',
        'status',
        'catatan',
        'tarikh_tindakan'
    
    ];
    
    


    public function courseRegistration()
    {
        return $this->belongsTo(CourseRegistration::class, 'pendaftaran_id', 'id');
    }
    public function user()
    {
        return $this->belongsTo(User::class, 'user_id', 'id');
    }	




}
